      const result=await api('/api/game-library',{method:'POST',body:JSON.stringify({path:item.path,enabled})});
      state.overview=result.overview||await api('/api/overview');state.status={...state.status,id:state.overview.id,revision:state.overview.revision,state:state.overview.state};state.lastRefresh=Date.now();
      state.cameraCache.clear();state.tree.records.clear();state.mapLocked=false;state.mapBase=null;state.focusVersion++;updateNavigation();renderStatus();await loadRoute(false);renderSelection();
