    const add=(label,action,options={})=>{const button=document.createElement('button');button.type='button';button.setAttribute('role','menuitem');button.textContent=label;button.dataset.action=options.key||'';button.disabled=!!options.disabled;if(options.danger)button.className='danger';if(options.title)button.title=options.title;button.addEventListener('click',()=>{hideContextMenu();action();});menu.append(button);};
