      const status=await api('/api/status');const was=state.status.state;const revisionChanged=state.overview&&state.overview.id===status.id&&Number(state.overview.revision||0)!==Number(status.revision||0);const staleTerminal=status.state!=='running'&&state.overview&&(state.overview.id!==status.id||Number(state.overview.size)!==Number(status.bytes)||state.overview.state!==status.state);state.status=status;renderStatus();renderSelection();
