  function showWarnings(){const list=$('warnings-list');list.replaceChildren();const warnings=state.overview?.warnings||[];warnings.forEach(warning=>{const row=document.createElement('div');row.className='warning-row';if(typeof warning==='string')row.textContent=warning;else{const path=document.createElement('strong');path.textContent=warning.path||'Unavailable path';const message=document.createElement('span');message.textContent=warning.message||warning.error||String(warning);row.append(path,message);}list.append(row);});if(!warnings.length){const p=document.createElement('p');p.textContent='The scan reported unavailable paths. Detailed messages may appear after the current scan finishes.';list.append(p);}if(Number(state.overview?.warningCount)>warnings.length){const p=document.createElement('p');p.textContent='Showing '+count(warnings.length)+' messages of '+count(state.overview.warningCount)+' unavailable paths.';list.append(p);}$('warnings-dialog').showModal();}
