    $('fullscreen-button').addEventListener('click',enterImmersive);$('immersive-exit').addEventListener('click',exitImmersive);$('immersive-navigation').addEventListener('click',()=>toggleImmersivePanel('Navigation'));$('immersive-contents').addEventListener('click',()=>toggleImmersivePanel('Contents'));$('immersive-menu').addEventListener('click',()=>toggleImmersivePanel('Menu'));$('immersive-up').addEventListener('click',goUp);
