    $('info-button').addEventListener('click',()=>$('info-dialog').showModal());$('warnings-button').addEventListener('click',showWarnings);document.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
    $('copy-path').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.detail.path);toast('Path copied.');}catch{$('detail-path').focus();toast('Select the path above to copy it.');}});$('reveal-item').addEventListener('click',async()=>{try{await api('/api/reveal',{method:'POST',body:JSON.stringify({path:state.detail.path})});toast('Opened in Windows Explorer.');}catch(error){toast(error.message);}});
    [$('search-input'),$('immersive-search-input')].forEach(input=>{input.addEventListener('input',event=>{const value=event.target.value.trim();clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>navigate({query:value,otherStart:0,groupOffset:0}),300);});input.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();if(state.immersive){event.stopPropagation();if(state.immersiveMenu){toggleImmersivePanel('Menu',false);$('immersive-menu').focus({preventScroll:true});}else exitImmersive();}else{input.value='';navigate({query:''});input.blur();}}if(event.key==='Enter'){clearTimeout(state.searchTimer);navigate({query:input.value.trim(),otherStart:0,groupOffset:0});}});});
